-- ไฟล์นี้รันได้อิสระ ไม่ต้องพึ่งไฟล์อื่น (idempotent)
-- ============================================================

begin;

-- ---------- เพิ่มหมวดหมู่ ----------
insert into categories (branch_id, code, name_th, sort_order)
select '448937cf-58c5-4007-b57b-6a8bcf46c2fe', 'design', 'การออกแบบระบบไฟฟ้าภายในอาคาร (Electrical Design)', 6
where not exists (
  select 1 from categories where branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and code = 'design'
);

-- ---------- เพิ่มคำถาม (33 ข้อ) ----------
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การคำนวณโหลดไฟฟ้าของอาคาร (Load Calculation) เพื่อออกแบบระบบไฟฟ้า มีขั้นตอนหลักอย่างไร', 'เริ่มจากรวบรวมโหลดทั้งหมดตามพื้นที่ใช้สอยและอุปกรณ์ไฟฟ้าที่คาดว่าจะติดตั้ง คูณด้วยตัวประกอบความต้องการใช้ไฟฟ้า (Demand Factor) เพื่อให้ได้โหลดที่คาดว่าจะใช้งานพร้อมกันจริง แล้วจึงนำไปเลือกขนาดหม้อแปลง สายไฟ และอุปกรณ์ป้องกันให้เหมาะสม', 'การคำนวณโหลดที่แม่นยำช่วยป้องกันทั้งปัญหาอุปกรณ์ไฟฟ้าเล็กเกินไปจนโอเวอร์โหลด และปัญหาลงทุนอุปกรณ์ใหญ่เกินความจำเป็นซึ่งสิ้นเปลืองงบประมาณ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การคำนวณโหลดไฟฟ้าของอาคาร (Load Calculation) เพื่อออกแบบระบบไฟฟ้า มีขั้นตอนหลักอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ตัวประกอบความต้องการใช้ไฟฟ้า (Demand Factor) แตกต่างจากตัวประกอบการใช้งาน (Utilization Factor) อย่างไร', 'Demand Factor คืออัตราส่วนระหว่างความต้องการใช้ไฟฟ้าสูงสุดต่อโหลดติดตั้งทั้งหมด สะท้อนว่าอุปกรณ์ทั้งหมดไม่ได้ทำงานพร้อมกันเต็มพิกัดในเวลาเดียวกัน ส่วน Utilization Factor คืออัตราส่วนของกำลังไฟฟ้าที่ใช้จริงต่อพิกัดของอุปกรณ์แต่ละชิ้นขณะทำงาน', 'ทั้งสองค่าล้วนใช้ในการประเมินขนาดโหลดจริงที่ระบบต้องรองรับให้ใกล้เคียงความเป็นจริงมากกว่าการรวมพิกัดอุปกรณ์ทั้งหมดโดยตรง ซึ่งจะได้ค่าที่สูงเกินจริงมาก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ตัวประกอบความต้องการใช้ไฟฟ้า (Demand Factor) แตกต่างจากตัวประกอบการใช้งาน (Utilization Factor) อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การเลือกขนาดสายไฟฟ้า (Cable Sizing) สำหรับวงจรหนึ่งๆ ต้องพิจารณาเกณฑ์ใดบ้างประกอบกัน', 'ต้องพิจารณาพิกัดกระแสที่สายทนได้ตามสภาพการติดตั้ง (Ampacity), แรงดันตกที่ยอมรับได้ตลอดความยาวสาย, พิกัดทนกระแสลัดวงจรช่วงสั้น และการประสานงานกับอุปกรณ์ป้องกันที่ต่ออยู่ปลายสาย', 'บางครั้งขนาดสายที่คำนวณจากพิกัดกระแสอาจเล็กพอ แต่เมื่อพิจารณาระยะทางไกลจนแรงดันตกเกินเกณฑ์ที่ยอมรับได้ (เช่น 3-5% ตามที่กำหนด) ก็จำเป็นต้องเลือกสายขนาดใหญ่ขึ้นเพื่อให้ผ่านทั้งสองเกณฑ์', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การเลือกขนาดสายไฟฟ้า (Cable Sizing) สำหรับวงจรหนึ่งๆ ต้องพิจารณาเกณฑ์ใดบ้างประกอบกัน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'แรงดันตกที่ยอมรับได้ (Voltage Drop) ในระบบไฟฟ้าภายในอาคารมีความสำคัญอย่างไร และเหตุใดจึงต้องจำกัดค่านี้ไว้', 'แรงดันตกที่มากเกินไปทำให้อุปกรณ์ไฟฟ้าปลายทางได้รับแรงดันต่ำกว่าที่ออกแบบไว้ ส่งผลให้อุปกรณ์ทำงานผิดปกติ เช่น มอเตอร์ดึงกระแสสูงขึ้น หลอดไฟส่องสว่างน้อยลง หรืออุปกรณ์อิเล็กทรอนิกส์ทำงานคลาดเคลื่อน', 'มาตรฐานทั่วไปมักกำหนดแรงดันตกสะสมตั้งแต่จุดจ่ายไฟจนถึงอุปกรณ์ปลายทางไม่ให้เกินประมาณ 5% ของแรงดันพิกัด โดยแบ่งสัดส่วนระหว่างสายป้อนหลักและวงจรย่อยตามความเหมาะสม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'แรงดันตกที่ยอมรับได้ (Voltage Drop) ในระบบไฟฟ้าภายในอาคารมีความสำคัญอย่างไร และเหตุใดจึงต้องจำกัดค่านี้ไว้'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'แผงจ่ายไฟฟ้าย่อย (Distribution Board หรือ Panel Board) ทำหน้าที่อะไรในระบบไฟฟ้าอาคาร', 'ทำหน้าที่รับไฟฟ้าจากสายป้อนหลัก แล้วกระจายไปยังวงจรย่อยต่างๆ ผ่านเบรกเกอร์ย่อยที่ติดตั้งอยู่ภายใน พร้อมทั้งเป็นจุดป้องกันวงจรย่อยแต่ละวงจรจากกระแสเกินหรือลัดวงจรแยกจากกัน', 'การจัดวางตำแหน่งแผงจ่ายไฟฟ้าย่อยที่เหมาะสมช่วยลดความยาวสายไฟที่ต้องเดินไปยังโหลดปลายทาง ซึ่งช่วยลดทั้งต้นทุนสายไฟและปัญหาแรงดันตกได้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'แผงจ่ายไฟฟ้าย่อย (Distribution Board หรือ Panel Board) ทำหน้าที่อะไรในระบบไฟฟ้าอาคาร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวงจรไฟฟ้าที่จ่ายให้ปลั๊กไฟในห้องน้ำหรือพื้นที่เปียกชื้น จึงต้องมีการป้องกันด้วยเครื่องตัดไฟรั่ว (Ground Fault Circuit Interrupter, GFCI) เพิ่มเติมจากเบรกเกอร์ปกติ', 'เพราะเบรกเกอร์ปกติออกแบบมาเพื่อป้องกันกระแสเกินและลัดวงจร แต่ไม่สามารถตรวจจับกระแสไฟฟ้ารั่วขนาดเล็กที่ไหลผ่านร่างกายมนุษย์ลงดินได้ ซึ่งกระแสระดับเพียงไม่กี่มิลลิแอมป์ก็เป็นอันตรายถึงชีวิตได้ในพื้นที่เปียกชื้นที่ความต้านทานร่างกายต่ำ', 'เครื่องตัดไฟรั่วทำงานโดยเปรียบเทียบกระแสที่ไหลเข้าและไหลออกจากวงจร หากไม่เท่ากันเกินค่าที่กำหนด (มักอยู่ที่ประมาณ 5-30 มิลลิแอมป์สำหรับป้องกันชีวิต) จะตัดวงจรทันทีภายในเสี้ยววินาที', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวงจรไฟฟ้าที่จ่ายให้ปลั๊กไฟในห้องน้ำหรือพื้นที่เปียกชื้น จึงต้องมีการป้องกันด้วยเครื่องตัดไฟรั่ว (Ground Fault Circuit Interrupter, GFCI) เพิ่มเติมจากเบรกเกอร์ปกติ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบสายดิน (Grounding System) ของอาคารมีวัตถุประสงค์หลักอะไร', 'เพื่อรักษาระดับศักย์ไฟฟ้าของโครงสร้างโลหะที่ไม่ได้มีไว้นำกระแสไฟฟ้าให้เท่ากับดิน ป้องกันอันตรายจากไฟฟ้าดูดหากมีกระแสไฟฟ้ารั่วมาสัมผัสกับโครงโลหะ และให้เส้นทางกระแสไฟฟ้าลงดินที่มีความต้านทานต่ำเพียงพอให้อุปกรณ์ป้องกันตัดวงจรได้อย่างรวดเร็ว', 'หากไม่มีระบบสายดินที่เหมาะสม เมื่อฉนวนของอุปกรณ์ไฟฟ้าเสื่อมสภาพและมีกระแสไฟฟ้ารั่วไปยังโครงโลหะ ผู้ที่สัมผัสโครงโลหะนั้นอาจได้รับอันตรายจากไฟฟ้าดูดโดยที่อุปกรณ์ป้องกันไม่ตัดวงจร', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบสายดิน (Grounding System) ของอาคารมีวัตถุประสงค์หลักอะไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบไฟฟ้าฉุกเฉิน (Emergency Power System) ในอาคารสูงมีความสำคัญอย่างไร และโดยทั่วไปจ่ายไฟให้ระบบใดบ้าง', 'มีความสำคัญในการรักษาความปลอดภัยของผู้ใช้อาคารเมื่อไฟฟ้าหลักดับ โดยทั่วไปจ่ายไฟให้ระบบที่จำเป็นต่อความปลอดภัยชีวิต เช่น ไฟฉุกเฉินและป้ายทางออก ลิฟต์ดับเพลิง ระบบสูบน้ำดับเพลิง ระบบอัดอากาศบันไดหนีไฟ และระบบแจ้งเหตุเพลิงไหม้', 'ระบบไฟฟ้าฉุกเฉินมักใช้เครื่องกำเนิดไฟฟ้าสำรอง (Standby Generator) ร่วมกับสวิตช์สับเปลี่ยนอัตโนมัติ (Automatic Transfer Switch หรือ ATS) เพื่อสับเปลี่ยนแหล่งจ่ายไฟฟ้าจากไฟฟ้าหลักไปเป็นเครื่องกำเนิดไฟฟ้าโดยอัตโนมัติเมื่อไฟฟ้าหลักดับ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบไฟฟ้าฉุกเฉิน (Emergency Power System) ในอาคารสูงมีความสำคัญอย่างไร และโดยทั่วไปจ่ายไฟให้ระบบใดบ้าง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'สวิตช์สับเปลี่ยนอัตโนมัติ (Automatic Transfer Switch, ATS) ทำงานตามลำดับขั้นตอนอย่างไรเมื่อไฟฟ้าหลักดับ', 'เมื่อตรวจพบว่าแรงดันไฟฟ้าหลักหายไปหรือต่ำกว่าเกณฑ์เป็นระยะเวลาหนึ่ง ATS จะสั่งให้เครื่องกำเนิดไฟฟ้าสำรองเริ่มทำงาน รอจนแรงดันและความถี่ของเครื่องกำเนิดไฟฟ้าคงที่ตามเกณฑ์ จากนั้นจึงสับเปลี่ยนโหลดจากแหล่งจ่ายหลักไปยังเครื่องกำเนิดไฟฟ้าสำรอง', 'เมื่อไฟฟ้าหลักกลับมาจ่ายปกติ ATS จะสับเปลี่ยนโหลดกลับไปใช้ไฟฟ้าหลักโดยอัตโนมัติ แล้วสั่งให้เครื่องกำเนิดไฟฟ้าทำงานต่อไปอีกช่วงเวลาสั้นๆ เพื่อระบายความร้อนก่อนหยุดเครื่อง (Cool Down Period)', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'สวิตช์สับเปลี่ยนอัตโนมัติ (Automatic Transfer Switch, ATS) ทำงานตามลำดับขั้นตอนอย่างไรเมื่อไฟฟ้าหลักดับ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การจัดวางเส้นทางเดินสายไฟฟ้า (Cable Routing) ในอาคาร ควรคำนึงถึงหลักการใดเพื่อความปลอดภัยและความสะดวกในการบำรุงรักษา', 'ควรแยกเส้นทางเดินสายไฟฟ้ากำลังออกจากสายสัญญาณอ่อน (เช่น สายโทรศัพท์หรือเครือข่ายคอมพิวเตอร์) เพื่อลดการรบกวนทางแม่เหล็กไฟฟ้า หลีกเลี่ยงเส้นทางที่ผ่านบริเวณเสี่ยงต่อความเสียหายทางกายภาพ และเผื่อพื้นที่สำหรับการขยายวงจรในอนาคต', 'การวางแผนเส้นทางเดินสายที่ดีตั้งแต่ขั้นตอนออกแบบ ช่วยลดปัญหาการเดินสายซับซ้อนยุ่งเหยิงและอำนวยความสะดวกต่อการตรวจสอบบำรุงรักษาในระยะยาว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การจัดวางเส้นทางเดินสายไฟฟ้า (Cable Routing) ในอาคาร ควรคำนึงถึงหลักการใดเพื่อความปลอดภัยและความสะดวกในการบำรุงรักษา'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'รางเดินสายไฟฟ้า (Cable Tray) แตกต่างจากท่อร้อยสายไฟฟ้า (Conduit) ในการใช้งานอย่างไร', 'รางเดินสายไฟฟ้าเป็นโครงสร้างเปิดที่รองรับสายไฟฟ้าจำนวนมากวางเรียงกัน เหมาะกับการเดินสายปริมาณมากในแนวยาวและระบายความร้อนได้ดี ส่วนท่อร้อยสายไฟฟ้าเป็นโครงสร้างปิดที่ป้องกันสายไฟฟ้าจากความเสียหายทางกายภาพและสภาพแวดล้อมได้ดีกว่า แต่รองรับจำนวนสายได้จำกัดกว่า', 'การเลือกใช้ขึ้นอยู่กับลักษณะพื้นที่ติดตั้ง เช่น พื้นที่เปิดโล่งภายในอาคารอุตสาหกรรมมักใช้รางเดินสาย ในขณะที่พื้นที่ที่ต้องการความสวยงามหรือป้องกันความเสียหายทางกายภาพมักใช้ท่อร้อยสาย', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'รางเดินสายไฟฟ้า (Cable Tray) แตกต่างจากท่อร้อยสายไฟฟ้า (Conduit) ในการใช้งานอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การจัดกลุ่มวงจรย่อย (Circuit Grouping) ในแผงจ่ายไฟฟ้าให้เหมาะสม มีประโยชน์อย่างไรต่อการบำรุงรักษาระบบ', 'การจัดกลุ่มวงจรตามพื้นที่หรือประเภทการใช้งาน (เช่น แยกวงจรแสงสว่างออกจากปลั๊กไฟ หรือแยกตามชั้นอาคาร) ช่วยให้สามารถระบุและแก้ไขปัญหาได้รวดเร็วขึ้นเมื่อเกิดความผิดปกติ อีกทั้งยังช่วยจำกัดผลกระทบเมื่อวงจรใดวงจรหนึ่งขัดข้อง ไม่ให้กระทบพื้นที่กว้างเกินความจำเป็น', 'การติดป้ายระบุวงจรอย่างชัดเจนที่แผงจ่ายไฟฟ้าเป็นส่วนสำคัญที่ช่วยให้ผู้ปฏิบัติงานบำรุงรักษาสามารถทำงานได้อย่างปลอดภัยและมีประสิทธิภาพ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การจัดกลุ่มวงจรย่อย (Circuit Grouping) ในแผงจ่ายไฟฟ้าให้เหมาะสม มีประโยชน์อย่างไรต่อการบำรุงรักษาระบบ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบไฟฟ้าแบบ TN, TT และ IT ตามมาตรฐานสากล แตกต่างกันในการต่อกราวด์อย่างไร', 'ระบบ TN มีการต่อจุดนิวทรัลของแหล่งจ่ายลงดินโดยตรง และโครงโลหะของอุปกรณ์ต่อกับตัวนำป้องกัน (Protective Earth) ที่เชื่อมโยงกลับไปยังจุดต่อดินของแหล่งจ่าย ระบบ TT มีการต่อจุดนิวทรัลลงดินที่แหล่งจ่าย แต่โครงโลหะของอุปกรณ์ต่อลงดินแยกต่างหากที่บริเวณติดตั้ง ส่วนระบบ IT ไม่มีการต่อจุดนิวทรัลลงดินโดยตรง หรือต่อผ่านอิมพีแดนซ์สูง', 'การเลือกใช้ระบบใดขึ้นอยู่กับข้อกำหนดของแต่ละประเทศและลักษณะการใช้งาน เช่น ระบบ IT นิยมใช้ในโรงพยาบาลบางพื้นที่ที่ต้องการความต่อเนื่องของไฟฟ้าสูงแม้เกิดความผิดพร่องลงดินครั้งแรก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบไฟฟ้าแบบ TN, TT และ IT ตามมาตรฐานสากล แตกต่างกันในการต่อกราวด์อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การป้องกันฟ้าผ่า (Lightning Protection System) สำหรับอาคาร ประกอบด้วยส่วนประกอบหลักใดบ้าง', 'ประกอบด้วยตัวนำล่อฟ้า (Air Terminal) ที่ติดตั้งบนยอดอาคารเพื่อรับฟ้าผ่า ตัวนำลงดิน (Down Conductor) ที่นำกระแสฟ้าผ่าจากตัวนำล่อฟ้าลงสู่พื้นดิน และระบบรากสายดิน (Grounding Electrode System) ที่กระจายพลังงานฟ้าผ่าลงสู่ดินอย่างปลอดภัย', 'นอกจากระบบป้องกันฟ้าผ่าโดยตรงแล้ว ยังต้องมีอุปกรณ์ป้องกันแรงดันเกินชั่วครู่ (Surge Protective Device) ติดตั้งในระบบไฟฟ้าภายในอาคาร เพื่อป้องกันแรงดันเกินที่อาจเหนี่ยวนำเข้าสู่ระบบไฟฟ้าผ่านสายไฟฟ้าหรือสายสัญญาณ แม้ฟ้าผ่าจะไม่ได้ลงที่ตัวอาคารโดยตรง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การป้องกันฟ้าผ่า (Lightning Protection System) สำหรับอาคาร ประกอบด้วยส่วนประกอบหลักใดบ้าง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การประสานศักย์ไฟฟ้า (Bonding) ในระบบไฟฟ้าอาคารแตกต่างจากการต่อลงดิน (Grounding) อย่างไร', 'Bonding คือการเชื่อมต่อส่วนที่เป็นโลหะต่างๆ ในอาคารเข้าด้วยกันทางไฟฟ้า เพื่อให้มีศักย์ไฟฟ้าเท่ากันทั้งหมด ป้องกันความต่างศักย์ที่อาจเกิดอันตรายเมื่อสัมผัสพร้อมกัน ส่วน Grounding คือการเชื่อมต่อระบบหรืออุปกรณ์ลงสู่พื้นดินโดยตรงเพื่อควบคุมศักย์ไฟฟ้าเทียบกับดิน', 'ทั้งสองระบบมักทำงานร่วมกัน เช่น ท่อน้ำโลหะ โครงสร้างเหล็กอาคาร และรางเดินสายไฟฟ้า ควรถูก Bond เข้าด้วยกันและเชื่อมต่อกับระบบ Grounding หลักของอาคาร เพื่อความปลอดภัยที่สมบูรณ์', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การประสานศักย์ไฟฟ้า (Bonding) ในระบบไฟฟ้าอาคารแตกต่างจากการต่อลงดิน (Grounding) อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวงจรไฟฟ้าสำหรับเครื่องปรับอากาศหรือมอเตอร์ขนาดใหญ่ จึงมักต้องออกแบบให้มีเบรกเกอร์แยกเฉพาะวงจร ไม่รวมกับวงจรแสงสว่างหรือปลั๊กไฟทั่วไป', 'เพราะมอเตอร์มีกระแสสตาร์ทสูงกว่ากระแสทำงานปกติมาก หากรวมอยู่ในวงจรเดียวกับโหลดอื่น กระแสสตาร์ทอาจทำให้เบรกเกอร์ตัดวงจรโดยไม่จำเป็น หรือทำให้แรงดันตกกระทบต่อโหลดอื่นในวงจรเดียวกันขณะมอเตอร์สตาร์ท', 'การแยกวงจรยังช่วยให้สามารถเลือกขนาดเบรกเกอร์และสายไฟที่เหมาะสมกับลักษณะกระแสของมอเตอร์โดยเฉพาะ ซึ่งแตกต่างจากการเลือกขนาดสำหรับโหลดคงที่ทั่วไป', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวงจรไฟฟ้าสำหรับเครื่องปรับอากาศหรือมอเตอร์ขนาดใหญ่ จึงมักต้องออกแบบให้มีเบรกเกอร์แยกเฉพาะวงจร ไม่รวมกับวงจรแสงสว่างหรือปลั๊กไฟทั่วไป'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การเลือกพิกัดตัดกระแสลัดวงจร (Short Circuit Rating) ของเบรกเกอร์ในแผงจ่ายไฟฟ้าอาคาร ต้องคำนึงถึงอะไรเป็นพิเศษเมื่ออยู่ใกล้หม้อแปลงจ่ายไฟหลัก', 'บริเวณใกล้หม้อแปลงจ่ายไฟหลักมักมีค่ากระแสลัดวงจรสูงที่สุดในระบบ เนื่องจากมีอิมพีแดนซ์ระหว่างแหล่งจ่ายกับจุดนั้นต่ำที่สุด จึงต้องเลือกเบรกเกอร์ที่มีพิกัดตัดกระแสสูงเพียงพอรองรับค่ากระแสลัดวงจรสูงสุดที่คำนวณได้ ณ ตำแหน่งนั้น', 'ยิ่งอยู่ห่างจากหม้อแปลงมากขึ้นตามสายไฟที่มีอิมพีแดนซ์เพิ่มขึ้น ค่ากระแสลัดวงจรก็จะลดลงตามลำดับ ทำให้สามารถเลือกเบรกเกอร์พิกัดต่ำลงได้ในวงจรที่อยู่ปลายทางมากขึ้น ซึ่งช่วยประหยัดต้นทุนอุปกรณ์', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การเลือกพิกัดตัดกระแสลัดวงจร (Short Circuit Rating) ของเบรกเกอร์ในแผงจ่ายไฟฟ้าอาคาร ต้องคำนึงถึงอะไรเป็นพิเศษเมื่ออยู่ใกล้หม้อแปลงจ่ายไฟหลัก'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'มาตรฐานการติดตั้งทางไฟฟ้าสำหรับประเทศไทย (วสท.) มีความสำคัญอย่างไรต่อการออกแบบระบบไฟฟ้าภายในอาคาร', 'เป็นเอกสารอ้างอิงหลักที่กำหนดข้อกำหนดขั้นต่ำด้านความปลอดภัยและวิธีปฏิบัติที่ถูกต้องในการออกแบบและติดตั้งระบบไฟฟ้าในประเทศไทย ครอบคลุมตั้งแต่การเลือกขนาดสาย การเดินสาย การต่อลงดิน ไปจนถึงระยะห่างความปลอดภัยต่างๆ', 'วิศวกรไฟฟ้าที่ออกแบบระบบไฟฟ้าอาคารในประเทศไทยจำเป็นต้องยึดถือมาตรฐานนี้เป็นพื้นฐาน ควบคู่กับกฎหมายควบคุมอาคารและข้อกำหนดของการไฟฟ้าที่เกี่ยวข้องในพื้นที่นั้นๆ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'มาตรฐานการติดตั้งทางไฟฟ้าสำหรับประเทศไทย (วสท.) มีความสำคัญอย่างไรต่อการออกแบบระบบไฟฟ้าภายในอาคาร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การออกแบบระบบไฟฟ้าแสงสว่างในอาคารสำนักงาน ต้องคำนึงถึงค่าความส่องสว่าง (Illuminance) อย่างไร', 'ต้องออกแบบให้ค่าความส่องสว่างบนพื้นที่ทำงานเหมาะสมกับลักษณะงานที่ทำ เช่น งานอ่านเขียนทั่วไปต้องการความส่องสว่างระดับหนึ่ง ในขณะที่งานที่ต้องการความละเอียดสูง เช่น งานตรวจสอบชิ้นงานขนาดเล็ก ต้องการความส่องสว่างที่สูงกว่า โดยพิจารณาทั้งปริมาณและคุณภาพแสง เช่น ความสม่ำเสมอและการไม่เกิดแสงจ้าบาดตา', 'การออกแบบระบบแสงสว่างที่ดีไม่ได้พิจารณาเพียงปริมาณแสงเพียงอย่างเดียว แต่ต้องคำนึงถึงประสิทธิภาพการใช้พลังงาน อายุการใช้งานของหลอดไฟ และความสบายตาของผู้ใช้งานควบคู่กันไป', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การออกแบบระบบไฟฟ้าแสงสว่างในอาคารสำนักงาน ต้องคำนึงถึงค่าความส่องสว่าง (Illuminance) อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบระบบไฟฟ้าอาคารสมัยใหม่จึงต้องเผื่อความจุสำรอง (Spare Capacity) สำหรับการขยายระบบในอนาคต', 'เพราะความต้องการใช้ไฟฟ้าของอาคารมักเพิ่มขึ้นตามกาลเวลา จากการเปลี่ยนแปลงการใช้งานพื้นที่ การเพิ่มอุปกรณ์ไฟฟ้าใหม่ หรือเทคโนโลยีที่เปลี่ยนแปลงไป การเผื่อความจุสำรองไว้ตั้งแต่แรกช่วยลดต้นทุนและความยุ่งยากในการปรับปรุงระบบไฟฟ้าทั้งหมดในอนาคต', 'การเผื่อความจุสำรองที่นิยมปฏิบัติ เช่น เผื่อพื้นที่ว่างในแผงจ่ายไฟฟ้าสำหรับเบรกเกอร์เพิ่มเติม หรือเลือกขนาดหม้อแปลงและสายป้อนหลักให้มีความจุมากกว่าโหลดคำนวณปัจจุบันในสัดส่วนที่เหมาะสม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบระบบไฟฟ้าอาคารสมัยใหม่จึงต้องเผื่อความจุสำรอง (Spare Capacity) สำหรับการขยายระบบในอนาคต'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การออกแบบระบบไฟฟ้าสำหรับห้องข้อมูล (Data Center) มีข้อกำหนดพิเศษอะไรที่แตกต่างจากอาคารทั่วไป', 'ต้องการความน่าเชื่อถือของระบบไฟฟ้าสูงมาก มักออกแบบให้มีระบบสำรองซ้ำซ้อน (Redundancy) เช่น มีแหล่งจ่ายไฟฟ้าสองเส้นทางอิสระ (Dual Feed) ระบบไฟฟ้าสำรองแบบไม่มีการขาดตอน (UPS) และเครื่องกำเนิดไฟฟ้าสำรองที่มีความจุเพียงพอสำหรับการทำงานต่อเนื่องเป็นเวลานาน', 'มาตรฐานความน่าเชื่อถือของ Data Center มักจำแนกเป็นระดับ Tier ต่างๆ ซึ่งกำหนดข้อกำหนดด้านความซ้ำซ้อนของระบบไฟฟ้าและระบบระบายความร้อนที่แตกต่างกันตามระดับความสำคัญของข้อมูลที่จัดเก็บ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การออกแบบระบบไฟฟ้าสำหรับห้องข้อมูล (Data Center) มีข้อกำหนดพิเศษอะไรที่แตกต่างจากอาคารทั่วไป'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบไฟฟ้าสำรองแบบไม่มีการขาดตอน (Uninterruptible Power Supply, UPS) ทำงานแตกต่างจากเครื่องกำเนิดไฟฟ้าสำรองอย่างไร', 'UPS ให้พลังงานไฟฟ้าต่อเนื่องทันทีโดยไม่มีการขาดตอนแม้เพียงเสี้ยววินาที เนื่องจากใช้พลังงานที่เก็บไว้ในแบตเตอรี่ผ่านวงจรอิเล็กทรอนิกส์ ในขณะที่เครื่องกำเนิดไฟฟ้าสำรองต้องใช้เวลาสตาร์ทเครื่องยนต์และปรับความเร็วรอบให้คงที่ก่อนจ่ายไฟฟ้าได้ ซึ่งมักใช้เวลาหลายวินาทีถึงหลายสิบวินาที', 'ระบบสำคัญมากที่ไม่สามารถทนต่อการขาดตอนของไฟฟ้าแม้เพียงชั่วขณะ เช่น เซิร์ฟเวอร์คอมพิวเตอร์ จึงมักออกแบบให้ใช้ UPS เป็นแหล่งจ่ายทันทีในช่วงที่ไฟฟ้าหลักดับ ก่อนที่เครื่องกำเนิดไฟฟ้าสำรองจะเริ่มทำงานและรับภาระต่อ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบไฟฟ้าสำรองแบบไม่มีการขาดตอน (Uninterruptible Power Supply, UPS) ทำงานแตกต่างจากเครื่องกำเนิดไฟฟ้าสำรองอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การจัดทำผังวงจรเส้นเดียว (Single Line Diagram) ของระบบไฟฟ้าอาคารมีประโยชน์อย่างไร', 'เป็นแผนภาพที่แสดงโครงสร้างของระบบไฟฟ้าทั้งหมดในรูปแบบเรียบง่าย โดยแสดงเพียงเส้นเดียวแทนวงจร 3 เฟส ช่วยให้เข้าใจภาพรวมของระบบ ลำดับการจ่ายไฟ ขนาดอุปกรณ์หลัก และจุดเชื่อมต่อต่างๆ ได้ง่ายโดยไม่ต้องแสดงรายละเอียดการเดินสายจริงทั้งหมด', 'ผังวงจรเส้นเดียวเป็นเอกสารสำคัญที่ใช้ทั้งในขั้นตอนออกแบบ การขออนุญาตก่อสร้าง และการบำรุงรักษาตลอดอายุการใช้งานของอาคาร จึงต้องปรับปรุงให้ตรงกับสภาพจริงเสมอเมื่อมีการเปลี่ยนแปลงระบบ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การจัดทำผังวงจรเส้นเดียว (Single Line Diagram) ของระบบไฟฟ้าอาคารมีประโยชน์อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบระบบไฟฟ้าอาคารจึงต้องพิจารณาแยกวงจรระหว่างโหลดที่สำคัญ (Essential Load) กับโหลดทั่วไป (Non-Essential Load)', 'เพื่อให้สามารถจัดลำดับความสำคัญในการจ่ายไฟฟ้าเมื่อเกิดสภาวะจำกัดกำลังไฟฟ้า เช่น ขณะใช้เครื่องกำเนิดไฟฟ้าสำรองที่มีความจุจำกัด โหลดสำคัญ เช่น ระบบความปลอดภัยชีวิตหรือระบบที่กระทบต่อการดำเนินธุรกิจอย่างรุนแรง ควรได้รับการจ่ายไฟฟ้าก่อนโหลดทั่วไปที่สามารถหยุดทำงานชั่วคราวได้โดยไม่ก่อความเสียหายร้ายแรง', 'การแยกวงจรนี้ยังช่วยให้สามารถกำหนดขนาดเครื่องกำเนิดไฟฟ้าสำรองให้เหมาะสมกับเฉพาะโหลดสำคัญ แทนที่จะต้องรองรับโหลดทั้งหมดของอาคารซึ่งจะมีต้นทุนสูงกว่ามาก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบระบบไฟฟ้าอาคารจึงต้องพิจารณาแยกวงจรระหว่างโหลดที่สำคัญ (Essential Load) กับโหลดทั่วไป (Non-Essential Load)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การเลือกตำแหน่งติดตั้งหม้อแปลงจ่ายไฟหลักของอาคาร ควรพิจารณาปัจจัยใดบ้าง', 'ควรพิจารณาระยะห่างจากศูนย์กลางโหลดเพื่อลดความยาวสายป้อนและปัญหาแรงดันตก การระบายความร้อนที่เพียงพอ ความปลอดภัยจากน้ำท่วมหรือความชื้น การเข้าถึงเพื่อบำรุงรักษาและกรณีฉุกเฉิน และระยะห่างความปลอดภัยตามข้อกำหนดที่เกี่ยวข้อง', 'ในอาคารสูง มักติดตั้งห้องหม้อแปลงไว้ที่ชั้นใต้ดินหรือชั้นล่างที่มีการระบายอากาศดี และหลีกเลี่ยงตำแหน่งที่เสี่ยงต่อน้ำท่วมขังในกรณีฝนตกหนักหรือน้ำท่วม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การเลือกตำแหน่งติดตั้งหม้อแปลงจ่ายไฟหลักของอาคาร ควรพิจารณาปัจจัยใดบ้าง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การประเมินโหลดสำหรับระบบไฟฟ้าของอาคารที่พักอาศัยรวม (เช่น คอนโดมิเนียม) แตกต่างจากอาคารสำนักงานอย่างไร', 'อาคารที่พักอาศัยมักมีรูปแบบการใช้ไฟฟ้าที่กระจายตัวตามเวลาแตกต่างกัน (เช่น ช่วงเย็นถึงค่ำมีการใช้ไฟฟ้าสูงสุด) และมีตัวประกอบความหลากหลาย (Diversity Factor) ระหว่างยูนิตที่พักแต่ละห้องค่อนข้างสูง เนื่องจากไม่ใช่ทุกห้องจะใช้ไฟฟ้าสูงสุดพร้อมกัน ต่างจากอาคารสำนักงานที่มักมีรูปแบบการใช้ไฟฟ้าที่ใกล้เคียงกันมากกว่าในช่วงเวลาทำการ', 'การประเมินโหลดที่แม่นยำตามลักษณะการใช้งานจริงของแต่ละประเภทอาคาร ช่วยให้ออกแบบขนาดหม้อแปลงและสายป้อนหลักได้เหมาะสม ไม่ใหญ่เกินความจำเป็นซึ่งจะเพิ่มต้นทุนก่อสร้างโดยไม่จำเป็น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การประเมินโหลดสำหรับระบบไฟฟ้าของอาคารที่พักอาศัยรวม (เช่น คอนโดมิเนียม) แตกต่างจากอาคารสำนักงานอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวงจรไฟฟ้าที่จ่ายให้ลิฟต์โดยสารจึงมักต้องมีทั้งวงจรไฟฟ้ากำลังและวงจรควบคุมแยกจากกัน', 'วงจรไฟฟ้ากำลังจ่ายพลังงานให้มอเตอร์ขับเคลื่อนลิฟต์ ในขณะที่วงจรควบคุมจ่ายไฟฟ้าให้ระบบอิเล็กทรอนิกส์ควบคุมการทำงาน เช่น ระบบเซฟตี้และปุ่มกด การแยกวงจรช่วยให้ระบบควบคุมยังทำงานได้แม้วงจรกำลังหลักเกิดปัญหา เช่น สามารถแจ้งเตือนหรือเปิดประตูฉุกเฉินได้แม้มอเตอร์ไม่ทำงาน', 'มาตรฐานความปลอดภัยลิฟต์กำหนดให้มีระบบไฟฟ้าสำรองสำหรับระบบควบคุมและระบบสื่อสารในลิฟต์ เพื่อความปลอดภัยของผู้โดยสารในกรณีไฟฟ้าดับระหว่างที่ลิฟต์กำลังทำงาน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวงจรไฟฟ้าที่จ่ายให้ลิฟต์โดยสารจึงมักต้องมีทั้งวงจรไฟฟ้ากำลังและวงจรควบคุมแยกจากกัน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การคำนวณขนาดเครื่องกำเนิดไฟฟ้าสำรอง (Standby Generator) ต้องพิจารณาปัจจัยใดนอกเหนือจากผลรวมโหลดที่ต้องการสำรอง', 'ต้องพิจารณากระแสสตาร์ทของมอเตอร์ขนาดใหญ่ที่อาจเชื่อมต่อพร้อมกัน เนื่องจากกระแสสตาร์ทสูงกว่ากระแสทำงานปกติมาก อาจทำให้เครื่องกำเนิดไฟฟ้าที่เลือกขนาดตามโหลดทำงานปกติเพียงอย่างเดียวไม่เพียงพอ รวมถึงระดับความสูงของสถานที่ติดตั้งที่มีผลต่อประสิทธิภาพของเครื่องยนต์', 'ในทางปฏิบัติ มักมีการวางแผนลำดับการสตาร์ทโหลดขนาดใหญ่ทีละตัว (Sequential Starting) แทนที่จะสตาร์ทพร้อมกันทั้งหมด เพื่อลดขนาดเครื่องกำเนิดไฟฟ้าที่ต้องใช้ลงได้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การคำนวณขนาดเครื่องกำเนิดไฟฟ้าสำรอง (Standby Generator) ต้องพิจารณาปัจจัยใดนอกเหนือจากผลรวมโหลดที่ต้องการสำรอง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบระบบไฟฟ้าในพื้นที่เสี่ยงอันตราย (Hazardous Area) เช่น พื้นที่จัดเก็บสารไวไฟ จึงต้องใช้อุปกรณ์ไฟฟ้าพิเศษ', 'เพราะอุปกรณ์ไฟฟ้าทั่วไปอาจเกิดประกายไฟหรือความร้อนสูงในการทำงานปกติหรือขณะเกิดความผิดปกติ ซึ่งอาจจุดระเบิดไอระเหยของสารไวไฟในบรรยากาศได้ อุปกรณ์ไฟฟ้าที่ใช้ในพื้นที่เสี่ยงอันตรายจึงต้องออกแบบพิเศษ เช่น แบบกันระเบิด (Explosion Proof) ที่ป้องกันไม่ให้ประกายไฟภายในลุกลามออกสู่ภายนอก', 'การจำแนกพื้นที่เสี่ยงอันตราย (Area Classification) ตามความน่าจะเป็นของการมีบรรยากาศไวไฟ เป็นขั้นตอนสำคัญที่ต้องทำก่อนเลือกใช้อุปกรณ์ไฟฟ้าที่เหมาะสมกับแต่ละโซนพื้นที่', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบระบบไฟฟ้าในพื้นที่เสี่ยงอันตราย (Hazardous Area) เช่น พื้นที่จัดเก็บสารไวไฟ จึงต้องใช้อุปกรณ์ไฟฟ้าพิเศษ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การออกแบบระบบไฟฟ้าที่คำนึงถึงประสิทธิภาพพลังงาน (Energy Efficient Design) มีแนวทางหลักอะไรบ้าง', 'มีแนวทางหลายด้าน เช่น เลือกใช้อุปกรณ์ไฟฟ้าประสิทธิภาพสูง ออกแบบระบบแสงสว่างให้ใช้พลังงานอย่างเหมาะสมพร้อมระบบควบคุมอัตโนมัติ (เช่น เซนเซอร์ตรวจจับการเคลื่อนไหวหรือแสงธรรมชาติ) ลดความยาวสายไฟและแรงดันตกที่ไม่จำเป็น และพิจารณาปรับปรุงตัวประกอบกำลังของระบบให้อยู่ในเกณฑ์ที่เหมาะสม', 'การออกแบบที่คำนึงถึงประสิทธิภาพพลังงานตั้งแต่แรกไม่เพียงช่วยลดค่าไฟฟ้าระยะยาว แต่ยังสอดคล้องกับมาตรฐานอาคารเขียวและข้อกำหนดด้านการอนุรักษ์พลังงานที่หลายประเทศเริ่มบังคับใช้มากขึ้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การออกแบบระบบไฟฟ้าที่คำนึงถึงประสิทธิภาพพลังงาน (Energy Efficient Design) มีแนวทางหลักอะไรบ้าง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการตรวจสอบและทดสอบระบบไฟฟ้า (Commissioning) ก่อนส่งมอบอาคารจึงมีความสำคัญ แม้จะออกแบบและติดตั้งตามแบบแล้วก็ตาม', 'เพราะการติดตั้งจริงอาจมีความคลาดเคลื่อนจากแบบเนื่องจากข้อจำกัดหน้างาน หรือความผิดพลาดในการติดตั้ง การทดสอบ Commissioning ช่วยยืนยันว่าระบบทำงานถูกต้องตามที่ออกแบบไว้จริง ก่อนที่จะเริ่มใช้งานเต็มรูปแบบ ลดความเสี่ยงที่จะพบปัญหาภายหลังที่แก้ไขยากกว่า', 'การทดสอบ Commissioning ระบบไฟฟ้ามักครอบคลุมการทดสอบระบบป้องกัน การทดสอบระบบไฟฟ้าสำรอง การตรวจวัดค่าความต้านทานฉนวนและสายดิน และการตรวจสอบการทำงานร่วมกันของระบบต่างๆ ในสภาวะจำลองเหตุการณ์จริง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการตรวจสอบและทดสอบระบบไฟฟ้า (Commissioning) ก่อนส่งมอบอาคารจึงมีความสำคัญ แม้จะออกแบบและติดตั้งตามแบบแล้วก็ตาม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การออกแบบระบบไฟฟ้าให้รองรับการติดตั้งแผงโซลาร์เซลล์บนหลังคาอาคารในอนาคต ควรเผื่อความพร้อมด้านใดไว้ล่วงหน้า', 'ควรเผื่อพื้นที่และเส้นทางเดินสายสำหรับอินเวอร์เตอร์และสายไฟจากแผงโซลาร์เซลล์ เผื่อช่องว่างในแผงจ่ายไฟฟ้าสำหรับเบรกเกอร์เชื่อมต่อระบบผลิตไฟฟ้า และพิจารณาความสามารถของระบบป้องกันในการรองรับกระแสไหลย้อนทิศทางจากระบบผลิตไฟฟ้าเข้าสู่ระบบจำหน่าย', 'การเผื่อความพร้อมตั้งแต่ขั้นตอนออกแบบครั้งแรกช่วยลดต้นทุนและความยุ่งยากในการปรับปรุงระบบไฟฟ้าอย่างมาก เมื่อเทียบกับการติดตั้งระบบผลิตไฟฟ้าเพิ่มเติมภายหลังที่ระบบเดิมไม่ได้เผื่อรองรับไว้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การออกแบบระบบไฟฟ้าให้รองรับการติดตั้งแผงโซลาร์เซลล์บนหลังคาอาคารในอนาคต ควรเผื่อความพร้อมด้านใดไว้ล่วงหน้า'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการออกแบบระบบไฟฟ้าอาคาร จึงต้องมีการประสานงานกับงานระบบอื่น เช่น งานสถาปัตยกรรมและงานปรับอากาศ ตั้งแต่ขั้นตอนออกแบบ', 'เพราะระบบไฟฟ้าต้องใช้พื้นที่ร่วมกับงานระบบอื่น เช่น เส้นทางเดินท่อปรับอากาศ ฝ้าเพดาน และโครงสร้างอาคาร หากไม่ประสานงานตั้งแต่แรก อาจเกิดปัญหาการชนกันของงานระบบ (Clash) ที่ต้องแก้ไขหน้างานซึ่งเสียเวลาและต้นทุนมากกว่าการแก้ไขในขั้นตอนออกแบบ', 'ปัจจุบันการออกแบบด้วยแบบจำลองสารสนเทศอาคาร (BIM) ช่วยให้ตรวจพบและแก้ไขปัญหาการชนกันของงานระบบต่างๆ ได้ตั้งแต่ขั้นตอนออกแบบก่อนเริ่มการก่อสร้างจริง ลดปัญหาที่อาจเกิดขึ้นหน้างานได้อย่างมาก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการออกแบบระบบไฟฟ้าอาคาร จึงต้องมีการประสานงานกับงานระบบอื่น เช่น งานสถาปัตยกรรมและงานปรับอากาศ ตั้งแต่ขั้นตอนออกแบบ'
  );

commit;

-- ---------- ตรวจสอบผลลัพธ์ ----------
select c.name_th as category, count(q.id) as question_count
from categories c
left join questions q on q.category_id = c.id
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'design'
group by c.name_th;
